"""Synthetic-only proof of a TWO-PERSON stage image generated by FLUX Kontext.

ONE official public ZeroGPU submission. No user photos/face data, token,
payments, or automatic retry on uncertain submission. Pass only if model
produces NEW visual scene, not the original side-by-side reference.
"""
from gradio_client import Client,handle_file
from PIL import Image,ImageDraw,ImageChops,ImageStat
from pathlib import Path
import hashlib,json,shutil,time

TARGET=Path("scene-stage-v433")
TARGET.mkdir(exist_ok=True)
source=Image.new("RGB",(768,768),(28,30,44))
d=ImageDraw.Draw(source)
for cx,colour in ((205,(45,124,210)),(555,(244,111,70))):
    d.ellipse((cx-57,90,cx+57,218),fill=(225,173,121))
    d.rounded_rectangle((cx-86,222,cx+86,503),20,fill=colour)
    d.line((cx-45,500,cx-55,700),fill=(30,31,52),width=40)
    d.line((cx+45,500,cx+55,700),fill=(30,31,52),width=40)
    d.line((cx-70,260,cx-125,390),fill=(225,173,121),width=32)
    d.line((cx+70,260,cx+125,390),fill=(225,173,121),width=32)
d.line((384,10,384,756),fill=(134,140,150),width=3)
src=TARGET/"two-illustrated-actors-reference.png"
source.save(src)
prompt=("Transform this TWO-portrait input into ONE photorealistic outdoor "
    "concert scene at the ancient Caesarea Roman amphitheater in Israel, "
    "under dramatic nighttime stage spotlights. Both performers stand "
    "TOGETHER on the SAME stage, full-body, holding microphones and "
    "singing in front of a vast crowded audience of thousands. "
    "Their two distinct outfits remain blue (left person) and orange (right person). "
    "Remove all portrait frames, borders, collage dividers and split-screen panels. "
    "Use one continuous camera viewpoint with depth, believable human-scale bodies, "
    "a microphone stand, stage monitors and audience lights. Absolutely NOT a "
    "side-by-side comparison photo or two vertical independent portrait panels.")
start=time.monotonic()
client=Client("black-forest-labs/FLUX.1-Kontext-dev",verbose=False)
job=client.submit(handle_file(str(src)),prompt,42,False,2.5,16,api_name="/infer")
deadline=start+460
while not job.done() and time.monotonic()<deadline:
    time.sleep(12)
if not job.done():
    job.cancel()
    raise TimeoutError("Community GPU image-stage job timed out; no second submission")
result=job.result()
source_img=result[0] if isinstance(result,(list,tuple)) else result
if isinstance(source_img,dict):
    source_img=source_img.get("path") or source_img.get("name")
if not isinstance(source_img,str) or not Path(source_img).is_file():
    raise ValueError("No generated scene returned")
with Image.open(source_img) as out:
    changed=out.convert("RGB").resize((768,768))
    mae=ImageStat.Stat(ImageChops.difference(source,changed)).mean
    difference=sum(mae)/3
    output=TARGET/"generated-shared-stage-preview.png"
    changed.save(output)
    from PIL import ImageStat
    print("NEW_STAGE_DIFFERENCE",difference,flush=True)
assert difference>25,("Model returned near-copy, not a generated stage",difference)
receipt={
 "generated_stage_image":True,
 "two_subject_source":"SYNTHETIC drawn identities only",
 "image_edit_provider":"black-forest-labs/FLUX.1-Kontext-dev",
 "mean_pixel_diff_from_original":difference,
 "scene_semantics_verified":False,
 "actor_identities_verified":False,
 "legal_commercial_rights_verified":False,
 "GPU_unlimited_free":False,
 "model_elapsed_seconds":round(time.monotonic()-start,1),
 "sha256":hashlib.sha256(output.read_bytes()).hexdigest()
}
(TARGET/"receipt.json").write_text(json.dumps(receipt,indent=2),encoding="utf8")
print("SCENE_BUILDER_PROOF",json.dumps(receipt),flush=True)
